local p={frames=4500,capture_every=60,moves={{20,75,'up'},{160,164,'a'},{450,454,'a'},{800,804,'a'},{1100,1104,'b'},{1300,1304,'down'},{1500,1504,'a'},{1800,1804,'a'},{2100,2104,'a'},{2400,2404,'a'},{2700,2704,'b'},{3000,3004,'b'},{3300,3304,'a'},{3600,3604,'b'},{3900,3904,'b'}}}
p.setup=function()local sr=emu.memType.wsCartRam;for j,rec in ipairs({{1,136,99,0,16},{99,233,0,0,16},{1,157,157,0,16}})do for i,v in ipairs(rec)do emu.write(0x6c9f+(j-1)*5+i-1,v,sr)end end;emu.write16(0x72fd,0xe0ff,sr);emu.write16(0x72ff,0x05f5,sr);for _,id in ipairs({4,0x26,0x1a,0xf,8,0x1f})do local a=0x7309+(id//16)*2;emu.write16(a,emu.read16(a,sr)&~(1<<(id%16)),sr)endend
local o=assert(loadfile(os.getenv('LAYOUT_OBSERVER')))();p.tick=function(f,save,memory)o.tick(f,save,memory);if f==p.frames then o.finish(save)end end;return p
